 private boolean valid(String u){return u.matches("[A-Za-z0-9_.]{3,30}");} private String email(String u){return u.toLowerCase(Locale.US)+"@baghdadi.app";}
 private void register(String u,String p,TextView err,Button submit){auth.createUserWithEmailAndPassword(email(u),p).addOnCompleteListener(t->{if(!t.isSuccessful()){authBusy=false;submit.setEnabled(true);err.setText(Errors.text(t.getException()));return;}FirebaseUser uo=t.getResult().getUser();Map<String,Object> user=new HashMap<>();user.put("uid",uo.getUid());user.put("username",u);user.put("usernameLower",u.toLowerCase(Locale.US));user.put("avatar",AV);user.put("createdAt",FieldValue.serverTimestamp());user.put("lastSeen",FieldValue.serverTimestamp());DocumentReference ur=fs.collection("usernames").document(u.toLowerCase(Locale.US));DocumentReference pr=fs.collection("users").document(uo.getUid());fs.runTransaction(tx->{DocumentSnapshot s=tx.get(ur);if(s.exists())throw new FirebaseFirestoreException("اسم المستخدم مستخدم بالفعل.",FirebaseFirestoreException.Code.ALREADY_EXISTS);tx.set(ur,Map.of("uid",uo.getUid(),"username",u,"createdAt",FieldValue.serverTimestamp()));tx.set(pr,user);return null;}).addOnCompleteListener(x->{if(!x.isSuccessful()){uo.delete();authBusy=false;submit.setEnabled(true);err.setText(Errors.text(x.getException()));}else{authBusy=false;submit.setEnabled(true);loadProfile(uo);}});});}
 private void loadProfile(FirebaseUser u){fs.collection("users").document(u.getUid()).get().addOnSuccessListener(d->{if(!d.exists()){handler.postDelayed(()->loadProfile(u),300);return;}me=new UserProfile();me.uid=u.getUid();me.username=String.valueOf(d.get("username"));me.usernameLower=String.valueOf(d.get("usernameLower"));me.avatar=String.valueOf(d.get("avatar"));showHome();}).addOnFailureListener(e->{if(!isFinishing())toast("تعذر تحميل الحساب: "+Errors.text(e));});}
